def C(names, *s): E(names, *s)
C('united states|usa|america|the us|united states of america', 'The United States is a federal republic of 50 states in North America.', 'It declared independence from Britain on 4 July 1776.',
  'Its capital is Washington, D.C., and its largest city is New York.', 'It has about 330 million people, the third-largest population in the world.', 'It expanded west across the continent in the 19th century.', 'It became a superpower after the Second World War.', 'Its economy is the largest in the world by nominal GDP.',
  'Its culture, technology and politics influence the whole world.')
C('united kingdom|uk|britain|great britain|england', 'The United Kingdom is a country made up of England, Scotland, Wales and Northern Ireland.', 'The Kingdom of Great Britain was formed in 1707; Ireland joined in 1801, and most of it left in 1922.',
  'Its capital is London.', 'It is a constitutional monarchy with a parliamentary democracy.', 'It led the Industrial Revolution and once ruled the largest empire in history.', 'It left the European Union in 2020.', 'English, its main language, is spoken worldwide.',
  'Its parliament, law and language have shaped many countries.')
C('france|french', 'France is a country in Western Europe.', 'Its modern republic dates back to the Revolution of 1789; the current Fifth Republic began in 1958.',
  'Its capital is Paris.', 'It has about 68 million people.', 'It is famous for its food, wine, fashion and art.', 'The Eiffel Tower was built for the 1889 World’s Fair.', 'It was a founding member of the European Union.',
  'It is one of the most visited countries in the world.')
C('germany|german', 'Germany is a country in central Europe.', 'It was first unified in 1871, divided after 1945, and reunified on 3 October 1990.',
  'Its capital is Berlin.', 'It has about 84 million people, the most in the EU.', 'It has Europe’s largest economy.', 'It is known for engineering, cars and beer.', 'It was split into East and West during the Cold War.',
  'It rebuilt itself into a stable democracy after the Second World War.')
C('italy|italian', 'Italy is a country in southern Europe, shaped like a boot.', 'It was unified in 1861 and became a republic in 1946.',
  'Its capital is Rome.', 'It was the heart of the Roman Empire and the birthplace of the Renaissance.', 'It has more UNESCO World Heritage Sites than almost any other country.', 'Vatican City, the world’s smallest country, lies inside Rome.',
  'Its food, art and history are loved worldwide.')
C('spain|spanish', 'Spain is a country in south-west Europe, on the Iberian Peninsula.', 'It was unified in the late 15th century.',
  'Its capital is Madrid.', 'Muslim rulers controlled much of it for centuries until 1492.', 'It built a huge empire in the Americas.', 'It had a civil war from 1936 to 1939, followed by Franco’s dictatorship until 1975.', 'Spanish is spoken by around 500 million people.',
  'It is a major centre of art, from Velázquez to Picasso.')
C('russia|russian federation', 'Russia is the largest country in the world by area.', 'The Russian state traces back to the 9th century; the Russian Federation formed in 1991.',
  'Its capital is Moscow.', 'It spans eleven time zones, across Europe and Asia.', 'It was ruled by tsars until 1917, then was the core of the Soviet Union.', 'It has about 145 million people.', 'Lake Baikal, in Siberia, is the world’s deepest lake.',
  'It has produced great writers, composers and scientists.')
C('china|people’s republic of china|prc', 'China is a country in East Asia with one of the world’s oldest civilisations.', 'The People’s Republic was founded on 1 October 1949.',
  'Its capital is Beijing, and its largest city is Shanghai.', 'It has about 1.4 billion people.', 'It is the world’s second-largest economy.', 'It is ruled by the Communist Party.', 'Its economic reforms began under Deng Xiaoping from 1978.',
  'It is now a global power in trade and technology.')
C('japan|japanese', 'Japan is an island country in East Asia.', 'It has had an emperor for over 1,500 years.',
  'Its capital is Tokyo, one of the largest cities in the world.', 'It is made up of four main islands and thousands of smaller ones.', 'It modernised rapidly after 1868.', 'It rebuilt after the Second World War into a major economy.', 'It is famous for technology, anime and its cuisine.',
  'It blends ancient tradition with cutting-edge modern life.')
C('india|indian', 'India is a country in South Asia, the world’s most populous nation.', 'It became independent from Britain in 1947 and a republic in 1950.',
  'Its capital is New Delhi.', 'It has over 1.4 billion people.', 'It is the world’s largest democracy.', 'Hundreds of languages are spoken there, with Hindi and English widely used.', 'It is the birthplace of Hinduism, Buddhism, Jainism and Sikhism.',
  'Its culture, food and film industry reach worldwide.')
C('brazil|brazilian', 'Brazil is the largest country in South America.', 'It became independent from Portugal in 1822.',
  'Its capital is Brasília; its largest cities are São Paulo and Rio de Janeiro.', 'Its official language is Portuguese.', 'It has about 215 million people.', 'Most of the Amazon rainforest is in Brazil.', 'It has won the football World Cup five times, more than any other country.',
  'Its music, from samba to bossa nova, is loved worldwide.')
C('canada|canadian', 'Canada is a country in North America, the second-largest in the world by area.', 'It became a self-governing dominion in 1867.',
  'Its capital is Ottawa.', 'Its official languages are English and French.', 'It has about 40 million people.', 'It has the world’s longest coastline.', 'Its head of state is the British monarch.',
  'It is known for its natural beauty and multicultural society.')
C('australia|australian', 'Australia is a country and continent in the southern hemisphere.', 'Aboriginal Australians have lived there for at least 50,000 years; it federated in 1901.',
  'Its capital is Canberra.', 'British colonisation began in 1788.', 'It has about 26 million people.', 'It is home to kangaroos, koalas and the Great Barrier Reef.', 'Most people live near the coast.',
  'It has the world’s oldest continuous cultures.')
C('egypt modern|modern egypt|egypt', 'Egypt is a country in North Africa and the Middle East.', 'Its modern state became independent from Britain in 1922.',
  'Its capital is Cairo.', 'It has over 100 million people.', 'Most Egyptians live along the Nile.', 'The Suez Canal opened in 1869.',
  'Its ancient monuments attract visitors from all over the world.')
C('mexico|mexican', 'Mexico is a country in North America.', 'It became independent from Spain in 1821.',
  'Its capital is Mexico City.', 'It has about 130 million people.', 'It was home to the Olmec, Maya and Aztec civilisations.', 'Chocolate, chilli and maize all come from Mexico.',
  'Its culture, food and Day of the Dead festival are famous worldwide.')
C('south africa', 'South Africa is the southernmost country in Africa.', 'It became a democracy in 1994, after apartheid.',
  'It has three capital cities: Pretoria, Cape Town and Bloemfontein.', 'It has 12 official languages.', 'Nelson Mandela was its first democratically elected president.',
  'It is called the “Rainbow Nation” for its diversity.')
C('israel', 'Israel is a country in the Middle East.', 'It declared independence on 14 May 1948.',
  'It was founded as a Jewish state after the Holocaust.', 'Its creation led to war with neighbouring Arab states.', 'The Israeli–Palestinian conflict has continued since.',
  'Jerusalem is holy to Jews, Christians and Muslims.')
C('south korea|korea', 'South Korea is a country in East Asia, on the southern half of the Korean Peninsula.', 'It was founded in 1948.',
  'Its capital is Seoul.', 'Korea was divided after the Second World War.', 'It grew from poverty to a rich, high-tech economy.', 'It is known for K-pop, film and companies like Samsung.',
  'Its rapid growth is called the “Miracle on the Han River”.')
C('north korea', 'North Korea is a country on the northern half of the Korean Peninsula.', 'It was founded in 1948.',
  'Its capital is Pyongyang.', 'It has been ruled by the Kim family since its founding.', 'It is one of the most isolated countries in the world.', 'It has developed nuclear weapons.',
  'It remains technically at war with South Korea.')
C('turkey|türkiye', 'Turkey is a country spanning south-east Europe and western Asia.', 'The Republic was founded in 1923 by Mustafa Kemal Atatürk.',
  'Its capital is Ankara, and its largest city is Istanbul.', 'It was the heart of the Ottoman Empire.', 'Atatürk modernised the country and introduced the Latin alphabet.',
  'It bridges Europe and Asia in culture and geography.')
C('iran', 'Iran is a country in western Asia, formerly known as Persia.', 'The Islamic Republic was established after the 1979 revolution.',
  'Its capital is Tehran.', 'It has one of the world’s oldest civilisations.', 'Persian, or Farsi, is its main language.',
  'Persian poetry, art and architecture are world-famous.')
C('ireland|irish', 'Ireland is an island in the North Atlantic, mostly occupied by the Republic of Ireland.', 'Most of Ireland became independent from the UK in 1922.',
  'Its capital is Dublin.', 'The Great Famine of 1845 to 1852 killed about a million people.', 'Millions emigrated, especially to the US.', 'Northern Ireland remains part of the UK.',
  'Irish literature and music are famous worldwide.')
C('greece modern|modern greece|greece', 'Greece is a country in south-east Europe.', 'It won independence from the Ottoman Empire in 1830.',
  'Its capital is Athens.', 'It has thousands of islands.', 'It is the birthplace of democracy and the Olympics.',
  'Its ancient ruins attract millions of visitors.')
C('netherlands|holland|dutch', 'The Netherlands is a country in north-western Europe.', 'It became independent from Spain in the 17th century.',
  'Its capital is Amsterdam.', 'About a quarter of it lies below sea level.', 'It built dykes and windmills to drain land.', 'It had a golden age of trade and art in the 1600s.',
  'It is famous for tulips, bicycles and canals.')
C('switzerland|swiss', 'Switzerland is a landlocked country in central Europe.', 'It traces its founding to 1291.',
  'Its capital is Bern.', 'It has four national languages.', 'It has stayed neutral in wars for centuries.', 'It is famous for watches, chocolate and banks.',
  'It is known for direct democracy, with frequent national votes.')
C('nigeria', 'Nigeria is a country in West Africa, the most populous in Africa.', 'It became independent from Britain in 1960.',
  'Its capital is Abuja, and its largest city is Lagos.', 'It has over 200 million people.', 'It has hundreds of ethnic groups.', 'Its film industry, Nollywood, is one of the largest in the world.',
  'It is a major cultural and economic power in Africa.')
C('argentina', 'Argentina is a country in South America.', 'It declared independence from Spain in 1816.',
  'Its capital is Buenos Aires.', 'It is famous for tango, beef and football.', 'It has won the World Cup three times.',
  'It stretches from the tropics to near Antarctica.')
